-- ─────────────────────────────────────────────────────────────
--  THE OLD WEBSITE'S NEWS — part 1 of 7: 127 articles that go live
--  Generated by scripts/import-old-news.py from Rich's export of the old WordPress database.
--  Run the news files in order, after the other files in supabase/legacy/ (SQL Editor → paste → Run), each once.
--
--  All 528 old articles: 186 league and competition articles from 2019 on go live, with their real dates.
--  The other 342 wait in Admin → News as drafts (Rich, round 30): Professional Snooker, CueViews,
--  Snooker Memories, and the old archive — whose articles all carry the date 1 January 2014 on the old site
--  (their real dates were lost long ago). Tick "Published" on any of them to put it on the website.
--  The text keeps its paragraphs, the opening paragraph and the pull quote. Pictures are not brought across
--  (Rich is sorting them): real-data/legacy/news-pictures.csv says which article had which picture.
--  None is "featured", so the News page and the banner keep showing the newest articles.
--  Nothing already on the website is changed. All one transaction.
-- ─────────────────────────────────────────────────────────────
begin;

do $$ begin
  if exists (select 1 from articles where slug in ('quadruple-joy-for-bugle-side', 'presentation-night-a-huge-success', 'new-season-new-website-new-beginnings', 'building-a-dynamic-website-for-the-future', 'results-and-scores-from-week-1-2019')) then
    raise exception 'This part of the old news is already in: nothing to do.';
  end if;
end $$;

insert into categories (name, sort)
  select r.name, 100 + row_number() over (order by r.name) from (values
  ('Competitions'),
  ('Cue View'),
  ('League Meetings'),
  ('League News'),
  ('Match Reports'),
  ('Professional Snooker'),
  ('Snooker Memories')) r(name)
  where not exists (select 1 from categories c where lower(c.name) = lower(r.name));

create temp table _news (title text, slug text, category text, more_categories jsonb, excerpt text, lead text, quote_text text, body text, published_at date, is_published boolean, author text) on commit drop;
insert into _news values
  ('Quadruple joy for Bugle side', 'quadruple-joy-for-bugle-side', 'Match Reports', '[]'::jsonb, 'Bugle A complete the quadruple more Bugle A completed the Quadruple of winning the Victory League, Team Handicap, Team Pairs and the Runabout Shield. Tregonissey B were very consistent all season and won the Rees…', null, null, 'Bugle A complete the quadruple more Bugle A completed the Quadruple of winning the Victory League, Team Handicap, Team Pairs and the Runabout Shield. Tregonissey B were very consistent all season and won the Rees League. There were many great finals hosted by local clubs at the end of the season. Darren Lock won the Singles 4-1 against Gary Spencer The Team Handicap Plate has been a successful new addition this year and was won by Lerryn. Gary Spencer came back from a 2-0 deficit to win the Bill Toms competition 3-2 on the final black against Steve Courts Richard Opie of Tregonissey won the Seniors and is one of the few players in league history that has won the Under 21''s, Singles and Seniors. The final award of the evening was the the Melville Mills Award which went to Chris Perring for his commitment and services to the St Blazey League and the Cornwall Billiards and Snooker Association. The award was presented to Chris by Matt Mills. There was also County success for Matt Green and Mark Ashton who won 4-3 against Paul Broad and Aiden Johns at St Day with the match finishing at 1:20am. Matt and Mark were also runners up in the St Blazey Snooker Doubles. After the Presentation Ceremony a Pasty supper was provided followed by music from the local group Cover Up. This year marked the 73rd year anniversary for the St Blazey and District League.', '2019-08-31', true, 'Richard Pearson'),
  ('Presentation night a huge success', 'presentation-night-a-huge-success', 'League News', '[]'::jsonb, 'Presentation Night Report more The St Blazey and District Snooker League recently held their end of season Presentation night at Bethel social club with over 70 people attending. Bugle A completed the Quadruple of…', null, null, 'Presentation Night Report more The St Blazey and District Snooker League recently held their end of season Presentation night at Bethel social club with over 70 people attending. Bugle A completed the Quadruple of winning the Victory League, Team Handicap, Team Pairs and the Runabout Shield. Tregonissey B were very consistent all season and won the Rees League. There were many great finals hosted by local clubs at the end of the season. Darren Lock won the Singles 4-1 against Gary Spencer The Team Handicap Plate has been a successful new addition this year and was won by Lerryn. Gary Spencer came back from a 2-0 deficit to win the Bill Toms competition 3-2 on the final black against Steve Courts Richard Opie of Tregonissey won the Seniors and is one of the few players in league history that has won the Under 21''s, Singles and Seniors. The final award of the evening was the the Melville Mills Award which went to Chris Perring for his commitment and services to the St Blazey League and the Cornwall Billiards and Snooker Association. The award was presented to Chris by Matt Mills. There was also County success for Matt Green and Mark Ashton who won 4-3 against Paul Broad and Aiden Johns at St Day with the match finishing at 1:20am. Matt and Mark were also runners up in the St Blazey Snooker Doubles. After the Presentation Ceremony a Pasty supper was provided followed by music from the local group Cover Up. This year marked the 73rd year anniversary for the St Blazey and District League.', '2019-09-01', true, 'Richard Pearson'),
  ('New season, new website, new beginnings', 'new-season-new-website-new-beginnings', 'League News', '[]'::jsonb, 'A warm welcome to one and all, yes the St Blazey and District Snooker League for 2019 is once more underway more This year we have had a complete overhaul of the website, produced an interactive electronic…', null, null, 'A warm welcome to one and all, yes the St Blazey and District Snooker League for 2019 is once more underway more This year we have had a complete overhaul of the website, produced an interactive electronic scoreboard, (more on that later) editable user profiles and management with CueView, player registration, password changes, automatic rankings and break calculations with statistics all being powered from the scorecard. As you can see unlike the previous website which focused on news amateur and professional we have listened to you all and have decided to focus purely on the league itself, the results, the fixtures and most importantly making it easier for you all to find the information you need quickly and easily. We have found over the years, that having League Republic, Facebook, Twitter and a dedicated website all a bit much, far to many places to interact with, so the idea to produce a new website that has everything on and is interactive for the end user was a top priority. Electronic Scorecard User Profiles Automatic Rankings Phase 3 Work Scheduled for next year now the final piece of the jigsaw it to male all the competitions behave in the same manner as the league results, a huge task, but an essential task and a very important task. Finally thank you to everyone who has helped get this website this far, a special thanks to my friend and genius Cristian, and to Clive, Geoff and Garry for all the help with stats and data.', '2019-09-04', true, 'Richard Pearson'),
  ('Building a dynamic website for the future', 'building-a-dynamic-website-for-the-future', 'League News', '[]'::jsonb, 'Week one a resounding success more So as the first week of the new season comes to an end, it''s time to reflect on what I call a resounding success, out of all the teams we only had 2 that didn''t use the new system.…', null, null, 'Week one a resounding success more So as the first week of the new season comes to an end, it''s time to reflect on what I call a resounding success, out of all the teams we only had 2 that didn''t use the new system. I have to tell you I was nervous about this, a year in development with groundbreaking features, up to midnight for the past week trying to get everything running nicely was hard, but I feel it went very well, feedback was good and uptake also very good, all in all well received. I have learnt about a few bugs and a few processes that need to be addressed moving forward not only into the following weeks but into phase 3 of the project which encompasses the competitions being moved into this format. I even managed to win my first game of the season in our great 5-0 win to the start of the season, shockingly I played alright considering i''m very tired and had no practice for 4 months!. Below I have listed some of the general feedback and areas to address, please feel free to add to this using the comments boxes below, and also I encourage you all to register on the site.

1. If card is edited at end of evening (not live) then when going to fixtures it shows the next fixture (next week) - we need a new box above next fixture for the live timeframe that says - current live fixture in play - then users can click on this (will save confusion)
2. Notifications - need to be better worded and feature players names, so for instance - Richard Pearson bt Justin Hooley 48-20 to put Tregonissey A 4-0 up
3. Adjust mobile styles to fit better on some devices
4. Remove player button needs to be more obvious
5. Make the submit final result more obvious (upload card) think this needs a little more validation, eg when all 5 frames are complete - it understands and prompts you to submit.
6. Inputs for scores/breaks should trigger mobile numerical keypad. Profile button to toggle notifications on/off

NEW FEATURES

1. Live scores page.
2. Player profile, Cueview and registration to amend your own content.
3. Live rankings
4. Live breaks

PHASE 3

1. Competition score cards
2. Further exciting additions to profiles', '2019-09-11', true, 'Richard Pearson'),
  ('Results and Scores from Week 1 - 2019', 'results-and-scores-from-week-1-2019', 'Match Reports', '[]'::jsonb, 'Fantastic 77 break by Andy Ridgeman gets new season underway', 'Fantastic 77 break by Andy Ridgeman gets new season underway', 'There was a very poignant occasion at St Neot at the start of the new season as the home side and Pelynt observed a minutes silence in memory of the late but great Austin Grose who passed away recently.', 'Memories of his match commentaries /slippers/and general chitchat will be remembered by many R.I.P Austin.

On the table Andy Ridgeman''s 77 break and Darren Locks win got the 2 home points as Pelynt sealed a fine win.

Treggy A have Barrie Macintosh back in the fold this year and expect to push hard for the title and whitewashed there B team with Jason Cocks having a 30 break.

Andy Peers had breaks of 34 25 19 to beat Rich Wilkinson as Bethel A beat there D team 4 1 with Dayle Dyche beating Matt Green for the away point.

Defending champs Bugle A picked up a good 4 1 win at Meva A with Ian Balls 51 break closing the evening.

Mike Williams took Bugle B''s only point at home to Meva B the as the away team made a great Start to the season.

Gorran took out Bugle C 4 1 to top the Rees league with Damien Knight stopping the whitewash.

Bethel C went 2 down to Lostwithiel after Darren Biggen and Craig Nicholls won but wins for Ben Stunnell, Courtney Crockford and Leigh Rosevear got the home victory.

St Blazey sneaked through by the odd frame at home to Lerryn with Mike Deleney record signing Richie Bolt and Mark Cockyne with Charles Mcmiram and Dave Vipond winners for the away side.

Top breaks of the week

